package com.aoo.bcg.hall.http;

import com.aoo.bcg.hall.room.JdbcHallRepository;
import com.aoo.bcg.hall.room.RoomCreateSaga;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpServer;
import java.io.IOException;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.util.*;
import core.replay.RecordReplayQueryService;

/** Canonical /api/v2/hall production HTTP entry; legacy room writes fail closed. */
public final class HallHttpRoutes {
 private HallHttpRoutes(){}
 public static void mount(HttpServer s,JdbcHallRepository r,HallRequestAuthenticator a,ObjectMapper j,RoomCreateSaga saga,RecordReplayQueryService records,String internalToken){Objects.requireNonNull(saga,"roomCreateSaga");Objects.requireNonNull(records,"recordReplayQueryService");if(internalToken==null||internalToken.length()<32)throw new IllegalArgumentException("hall internal token must contain at least 32 characters");s.createContext("/health/hall",e->reply(e,200,Map.of("status","UP","persistence","jdbc","roomCreateSaga","UP","recordReplay","UP"),j));s.createContext("/api/v2/hall",e->handle(r,a,j,saga,records,e));s.createContext("/internal/v1/hall/rooms",e->handleInternal(r,j,saga,internalToken,e));}
 private static void handleInternal(JdbcHallRepository r,ObjectMapper j,RoomCreateSaga saga,String token,HttpExchange e)throws IOException{String trace=Optional.ofNullable(e.getRequestHeaders().getFirst("X-Trace-Id")).filter(v->!v.isBlank()).orElseGet(()->UUID.randomUUID().toString());try{String supplied=Optional.ofNullable(e.getRequestHeaders().getFirst("X-Aoo-Internal-Token")).orElse("");if(!"POST".equals(e.getRequestMethod())||!java.security.MessageDigest.isEqual(token.getBytes(StandardCharsets.UTF_8),supplied.getBytes(StandardCharsets.UTF_8)))throw new HallError(403,"HALL_INTERNAL_FORBIDDEN","internal hall request rejected");Map<String,Object>b=new HashMap<>(body(e,j));String path=e.getRequestURI().getPath(),prefix="/internal/v1/hall/rooms/",suffix="/close";if(path.startsWith(prefix)&&path.endsWith(suffix)){String raw=path.substring(prefix.length(),path.length()-suffix.length());if(raw.isBlank()||!raw.chars().allMatch(Character::isDigit))throw new HallError(400,"HALL_INVALID_ROOM_ID","internal room id is invalid");long room=Long.parseLong(raw);String requestId=String.valueOf(b.remove("requestId")),reason=String.valueOf(b.getOrDefault("reason","AUTHORITY_REMOVED"));reply(e,200,Map.of("code","OK","data",r.closeRoom(room,requestId,reason,trace),"traceId",trace),j);return;}if(path.matches("/internal/v1/hall/rooms/\\d+/members/\\d+/leave")){String[]parts=path.split("/");long room=Long.parseLong(parts[5]),account=Long.parseLong(parts[7]);String requestId=String.valueOf(b.remove("requestId"));reply(e,200,Map.of("code","OK","data",r.authorityLeave(account,requestId,room,trace),"traceId",trace),j);return;}if(!"/internal/v1/hall/rooms".equals(path))throw new HallError(404,"HALL_INTERNAL_ROUTE_NOT_FOUND","internal hall route not found");long account=Long.parseLong(String.valueOf(b.remove("accountId")));String requestId=String.valueOf(b.remove("requestId"));b.remove("roomId");b.remove("stateVersion");b.put("roomId",r.allocateRoomId(account,requestId));b.put("stateVersion",1L);b.put("_traceId",trace);reply(e,200,Map.of("code","OK","data",saga.create(account,requestId,b),"traceId",trace),j);}catch(HallError x){reply(e,x.status(),Map.of("code",x.code(),"message",x.getMessage(),"traceId",trace),j);}catch(Exception x){Throwable root=x;while(root.getCause()!=null)root=root.getCause();System.err.println("hall internal request failed path="+e.getRequestURI().getPath()+" trace="+trace+" cause="+root.getClass().getSimpleName()+":"+String.valueOf(root.getMessage()));reply(e,400,Map.of("code","HALL_INVALID_INTERNAL_REQUEST","message","internal hall request is invalid","traceId",trace),j);}}
 private static void handle(JdbcHallRepository r,HallRequestAuthenticator a,ObjectMapper j,RoomCreateSaga saga,RecordReplayQueryService records,HttpExchange e)throws IOException{String trace=Optional.ofNullable(e.getRequestHeaders().getFirst("X-Trace-Id")).filter(v->!v.isBlank()).orElseGet(()->UUID.randomUUID().toString());try{long account=a.authenticate(e.getRequestHeaders().getFirst("Authorization"));String p=e.getRequestURI().getPath().substring("/api/v2/hall".length());Map<String,String>q=query(e.getRequestURI().getRawQuery());Object out;if("/play-filters".equals(p)&&"GET".equals(e.getRequestMethod()))out=r.playFilters(q.get("clientVersion"));else if("/catalog".equals(p)&&"GET".equals(e.getRequestMethod()))out=r.catalog(q.getOrDefault("regionCode","ALL"),q.get("clientVersion"));else if("/configuration".equals(p)&&"GET".equals(e.getRequestMethod()))out=r.configuration(Long.parseLong(q.getOrDefault("gameId","")),q.get("playVersion"),q.get("clientVersion"));else if("/history".equals(p)&&"GET".equals(e.getRequestMethod()))out=records.history(account,Long.parseLong(q.getOrDefault("beforeRoomId","0")),Integer.parseInt(q.getOrDefault("limit","20")));else if(p.matches("/history/\\d+")&&"GET".equals(e.getRequestMethod()))out=records.detail(account,roomId(p));else if(p.matches("/replays/\\d+/\\d+/chunks")&&"GET".equals(e.getRequestMethod())){String[] parts=p.split("/");out=records.replay(account,Long.parseLong(parts[2]),Integer.parseInt(parts[3]),Long.parseLong(q.getOrDefault("afterSequence","0")),Integer.parseInt(q.getOrDefault("limit","100")));}else if("/rooms".equals(p)&&"POST".equals(e.getRequestMethod())){String requestId=key(e);Map<String,Object>b=new HashMap<>(body(e,j));if(b.containsKey("regionCode")||b.containsKey("admission")||b.keySet().stream().anyMatch(key->key.startsWith("_admission")))throw HallError.bad("HALL_AUTHORITATIVE_FIELD_FORBIDDEN","authoritative routing or admission field is forbidden");Map<String,Object>admission=admission(e,b);b.put("_admissionIp",admission.get("ipAddress"));if(admission.containsKey("latitude")){b.put("_admissionLatitude",admission.get("latitude"));b.put("_admissionLongitude",admission.get("longitude"));}b.put("roomId",r.allocateRoomId(account,requestId));b.put("stateVersion",1L);b.put("_traceId",trace);out=saga.create(account,requestId,b);}else if(p.matches("/rooms/\\d+")&&"GET".equals(e.getRequestMethod()))out=r.room(account,roomId(p));else if(p.matches("/rooms/\\d+/join")&&"POST".equals(e.getRequestMethod())){Map<String,Object>b=body(e,j);out=r.join(account,key(e),roomId(p),trace,admission(e,b));}else if(p.matches("/rooms/\\d+/leave")&&"POST".equals(e.getRequestMethod()))out=r.leave(account,key(e),roomId(p));else if(p.matches("/rooms/\\d+/ticket")&&"POST".equals(e.getRequestMethod()))out=r.ticket(account,key(e),roomId(p),String.valueOf(body(e,j).get("deviceFingerprint")));else throw new HallError(404,"HALL_ROUTE_NOT_FOUND","hall route not found");reply(e,200,Map.of("code","OK","data",out,"traceId",trace),j);}catch(SecurityException x){reply(e,403,Map.of("code","HALL_RECORD_ACCESS_DENIED","message","无权查看该战绩或回放","traceId",trace),j);}catch(HallError x){reply(e,x.status(),Map.of("code",x.code(),"message",x.getMessage(),"traceId",trace),j);}catch(NumberFormatException x){reply(e,400,Map.of("code","HALL_INVALID_REQUEST","message","numeric field is invalid","traceId",trace),j);}catch(Exception x){Throwable root=x;while(root.getCause()!=null)root=root.getCause();System.err.println("hall request failed path="+e.getRequestURI().getPath()+" trace="+trace+" cause="+root.getClass().getSimpleName()+":"+String.valueOf(root.getMessage()));reply(e,500,Map.of("code","HALL_INTERNAL_ERROR","message","hall request failed","traceId",trace),j);}}
 private static Map<String,Object> body(HttpExchange e,ObjectMapper j)throws IOException{byte[]b=e.getRequestBody().readAllBytes();if(b.length==0)return Map.of();if(b.length>1048576)throw HallError.bad("HALL_INVALID_REQUEST","request body too large");return j.readValue(b,new TypeReference<>(){});}private static Map<String,Object>admission(HttpExchange e,Map<String,Object>body){if(body.containsKey("admission")||body.keySet().stream().anyMatch(key->key.startsWith("_admission")))throw HallError.bad("HALL_AUTHORITATIVE_FIELD_FORBIDDEN","internal admission fields are forbidden");Map<String,Object>out=new LinkedHashMap<>();out.put("ipAddress",e.getRemoteAddress().getAddress().getHostAddress());Object latitude=body.get("latitude"),longitude=body.get("longitude");if(latitude!=null||longitude!=null){if(!(latitude instanceof Number lat)||!(longitude instanceof Number lon))throw HallError.bad("HALL_INVALID_REQUEST","latitude and longitude must both be numeric");out.put("latitude",lat.doubleValue());out.put("longitude",lon.doubleValue());}return Map.copyOf(out);}private static long roomId(String p){return Long.parseLong(p.split("/")[2]);}private static String key(HttpExchange e){String value=e.getRequestHeaders().getFirst("X-Idempotency-Key");return value==null?e.getRequestHeaders().getFirst("Idempotency-Key"):value;}private static Map<String,String>query(String raw){Map<String,String>o=new HashMap<>();if(raw!=null)for(String pair:raw.split("&")){int i=pair.indexOf('=');if(i>0)o.put(URLDecoder.decode(pair.substring(0,i),StandardCharsets.UTF_8),URLDecoder.decode(pair.substring(i+1),StandardCharsets.UTF_8));}return o;}private static Map<String,Object>error(String c,String m){return Map.of("error",Map.of("code",c,"message",m));}private static void reply(HttpExchange e,int status,Object v,ObjectMapper j)throws IOException{byte[]b=j.writeValueAsBytes(v);e.getResponseHeaders().set("Content-Type","application/json; charset=utf-8");e.getResponseHeaders().set("Cache-Control","no-store");e.sendResponseHeaders(status,b.length);e.getResponseBody().write(b);e.close();}
}
